<template>
  <figure ref="root" class="view-gallery-live-stage index-ignore" :class="{ 'is-compact': compact }" :style="{ '--demo-aspect': `${designWidth}/${designHeight}` }">
    <ExpandableProjectMedia :title="`${activeLabel} demonstration`" :aspect-ratio="designWidth/designHeight" @change="onEnlarged">
    <div ref="canvas" class="view-gallery-live-canvas demo-open-surface" :aria-busy="frameMounted && !frameReady">
      <iframe
        v-if="frameMounted"
        ref="frame"
        :key="frameKey"
        :src="frameUrl"
        :style="frameStyle"
        :title="`${activeLabel} live demonstration`"
        tabindex="-1"
        allow="autoplay 'none'; fullscreen"
        @load="onFrameLoad"
      ></iframe>
      <div v-else class="view-gallery-live-poster">
        <img :src="posterSource" alt="" aria-hidden="true">
        <div>
          <span>The View Gallery</span>
          <i></i>
          <button v-if="requiresActivation" type="button" @click="activateFrame">Load demonstration</button>
          <p v-else>Preparing the Gallery</p>
        </div>
      </div>
      <div v-if="frameMounted && !frameReady" class="view-gallery-live-loading" role="status">
        <span></span><span></span><span></span>
        <em>Loading {{ activeLabel }}</em>
      </div>
      <DemoOpenLink :href="openUrl" :label="`Open ${activeLabel.toLowerCase()}`" />
    </div>
    <template #caption><figcaption>
      <div v-if="!mode" class="view-gallery-live-modes" role="tablist" aria-label="Choose a live Gallery scene">
        <button
          v-for="mode in modes"
          :key="mode.id"
          type="button"
          role="tab"
          :aria-selected="activeMode === mode.id"
          @click="selectMode(mode.id)"
        >
          <span>{{ mode.label }}</span>
          <small>{{ mode.copy }}</small>
        </button>
      </div>
      <p v-if="mode" class="view-gallery-caption">{{ activeMode === 'gallery' ? 'Explore the collection or bring a question of your own.' : 'Follow the narrative through its original works.' }}</p>
      <div class="view-gallery-live-actions">
        <button type="button" class="view-gallery-live-transport" :aria-label="darkDemo ? 'Use light theme in demonstration' : 'Use dark theme in demonstration'" :aria-pressed="darkDemo" @click="themeOverride = !darkDemo">
          <svg viewBox="0 0 20 20" aria-hidden="true"><path v-if="!darkDemo" d="M15.8 12A6.7 6.7 0 0 1 8 4.2a6.7 6.7 0 1 0 7.8 7.8Z"/><g v-else><circle cx="10" cy="10" r="3.3"/><path d="M10 1v2m0 14v2M1 10h2m14 0h2M3.6 3.6 5 5m10 10 1.4 1.4M3.6 16.4 5 15M15 5l1.4-1.4"/></g></svg>
        </button>
        <button type="button" class="view-gallery-live-transport" :aria-label="requiresActivation ? 'Play demonstration' : paused ? 'Continue demonstration' : 'Pause demonstration'" @click="togglePlayback">
          <svg viewBox="0 0 20 20" aria-hidden="true"><path v-if="paused || requiresActivation" d="m7 4 8 6-8 6Z"/><path v-else d="M7 4v12M13 4v12"/></svg>
        </button>
      </div>
    </figcaption></template>
    </ExpandableProjectMedia>
  </figure>
</template>

<script>
import DemoOpenLink from './DemoOpenLink.vue';
import ExpandableProjectMedia from './ExpandableProjectMedia.vue';
const DEMO_VIEW_ID = 'PNZPdB__yBeyYjkF';
const DEMO_WIDTH = 1440;
const DEMO_HEIGHT = 810;

export default {
  name: 'ViewGalleryLiveStage',
  components: { DemoOpenLink, ExpandableProjectMedia },
  emits: ['scene-change'],
  props: {
    compact: Boolean,
    mode: { type: String, default: '', validator: value => !value || ['gallery', 'exhibition'].includes(value) },
    initialMode: { type: String, default: 'gallery', validator: value => ['gallery', 'exhibition'].includes(value) },
    active: { type: Boolean, default: true },
    designWidth: { type: Number, default: 1440 },
    designHeight: { type: Number, default: 810 },
    showControls: Boolean,
    eager: Boolean,
  },
  data() {
    return {
      activeMode: this.mode || this.initialMode,
      nearViewport: false,
      inViewport: false,
      sceneArea: 'hall',
      pageVisible: true,
      frameActivated: false,
      constrainedDevice: false,
      frameScale: 1,
      paused: false,
      pageDark: document.body.classList.contains('dark-mode'),
      themeOverride: null,
      enlarged: false,
      frameReady: false,
      frameKey: 0,
      modes: [
        { id: 'gallery', label: 'Gallery', copy: 'Move through the shared Hall' },
        { id: 'exhibition', label: 'Exhibition', copy: 'Follow one generated View' },
      ],
    };
  },
  computed: {
    darkDemo(){return this.themeOverride ?? this.pageDark;},
    requiresActivation() { return this.constrainedDevice && !this.frameActivated; },
    frameMounted() { return (this.enlarged || (this.active && this.nearViewport)) && this.pageVisible && !this.requiresActivation; },
    activeLabel() { return this.activeMode === 'gallery' ? 'Gallery' : 'Exhibition'; },
    posterSource() { return this.activeMode === 'gallery' ? '/assets/img/view-gallery/hall-overview.webp' : '/assets/img/view-gallery/exhibition-controls.webp'; },
    channel() { return `view-gallery-live-${this.$.uid}`; },
    frameUrl() {
      const path = '/views';
      const showcase = this.activeMode === 'gallery' ? 'tour' : 'exhibition';
      const controls = this.activeMode === 'exhibition' || this.showControls ? '&showcaseControls=1' : '';
      const view = this.activeMode === 'exhibition' ? `&showcaseView=${DEMO_VIEW_ID}` : '';
      return `${window.location.pathname}#${path}?showcase=${showcase}&galleryFrame=1&showcaseLoop=1${controls}${view}&showcaseChannel=${this.channel}`;
    },
    openUrl() {
      const path = this.activeMode === 'gallery' ? '/views' : `/view/${DEMO_VIEW_ID}`;
      return `${window.location.pathname}#${path}?presentation=museum&temporaryPresentation=1`;
    },
    effectivePaused() { return this.paused || !this.pageVisible || !this.active || (!this.enlarged && !this.inViewport); },
    frameStyle() {
      return {
        width: `${this.designWidth || DEMO_WIDTH}px`,
        height: `${this.designHeight || DEMO_HEIGHT}px`,
        transform: `scale(${this.frameScale})`,
      };
    },
  },
  watch: {
    darkDemo() { this.sendTheme(); this.publishScene(); },
    effectivePaused() { this.sendPlaybackState(); this.publishScene(); },
    frameReady() { this.publishScene(); },
    mode(value) {
      if (!value || value === this.activeMode) return;
      this.activeMode = value;
      this.frameActivated = true;
      this.frameReady = false;
      this.paused = false;
      this.frameKey += 1;
    },
  },
  mounted() {
    window.addEventListener('message', this.onSceneReady);
    this._themeObserver=new MutationObserver(()=>{const dark=document.body.classList.contains('dark-mode');if(dark!==this.pageDark){this.pageDark=dark;this.themeOverride=null;}});
    this._themeObserver.observe(document.body,{attributes:true,attributeFilter:['class']});
    this.constrainedDevice = this.isConstrainedDevice();
    this.frameActivated = !this.constrainedDevice;
    this._resizeObserver = new ResizeObserver(() => this.measureFrame());
    this._resizeObserver.observe(this.$refs.canvas);
    this.measureFrame();
    this._visibility = () => { this.pageVisible = !document.hidden; };
    document.addEventListener('visibilitychange', this._visibility);
    this._observer = new IntersectionObserver(([entry]) => {
      const near = Boolean(entry?.isIntersecting);
      if (near) {
        clearTimeout(this._unmountTimer);
        this.nearViewport = true;
        return;
      }
      clearTimeout(this._unmountTimer);
      this._unmountTimer = setTimeout(() => {
        this.nearViewport = false;
        this.frameReady = false;
      }, 700);
    }, { rootMargin: this.eager ? '500px 0px' : '220px 0px', threshold: 0 });
    this._observer.observe(this.$refs.root);
    this._playbackObserver = new IntersectionObserver(([entry]) => {
      this.inViewport = Boolean(entry?.isIntersecting && entry.intersectionRatio >= .12);
    }, {threshold:[0,.12]});
    this._playbackObserver.observe(this.$refs.root);
  },
  beforeUnmount() {
    window.removeEventListener('message', this.onSceneReady);
    this._themeObserver?.disconnect();
    clearTimeout(this._unmountTimer);
    this._resizeObserver?.disconnect();
    this._observer?.disconnect();
    this._playbackObserver?.disconnect();
    document.removeEventListener('visibilitychange', this._visibility);
  },
  methods: {
    onEnlarged(value) {
      this.enlarged=value;
      if(value && this.requiresActivation) this.activateFrame();
    },
    onSceneReady(event) {
      if (event.origin !== location.origin || event.source !== this.$refs.frame?.contentWindow || event.data?.channel !== this.channel) return;
      if (event.data.type === 'view-gallery-showcase-ready') { this.sendTheme(); this.sendPlaybackState(); }
      if (event.data.type === 'view-gallery-showcase-place' && ['hall','directory','collection','compose','archive','about'].includes(event.data.area)) {
        this.sceneArea = event.data.area;
        this.publishScene();
      }
    },
    publishScene() { this.$emit('scene-change', { area:this.sceneArea, playing:this.activeMode==='gallery' && this.frameReady && !this.effectivePaused, dark:this.darkDemo }); },
    sendTheme() {
      this.$refs.frame?.contentWindow?.postMessage({ type:'view-gallery-showcase-theme', channel:this.channel, dark:this.darkDemo }, location.origin);
    },
    isConstrainedDevice() {
      return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    },
    measureFrame() {
      const width = parseFloat(getComputedStyle(this.$refs.canvas).width) || this.designWidth || DEMO_WIDTH;
      this.frameScale = (width + 1) / (this.designWidth || DEMO_WIDTH);
    },
    activateFrame() {
      this.frameActivated = true;
      this.frameReady = false;
    },
    togglePlayback() {
      if (this.requiresActivation) { this.activateFrame(); this.paused = false; return; }
      this.paused = !this.paused;
    },
    selectMode(mode) {
      if (mode === this.activeMode && this.frameMounted) {
        this.paused = false;
        return;
      }
      this.activeMode = mode;
      this.frameActivated = true;
      this.frameReady = false;
      this.paused = false;
      this.frameKey += 1;
    },
    onFrameLoad() {
      this.frameReady = true;
      this.sendTheme();
      this.sendPlaybackState();
    },
    sendPlaybackState() {
      this.$refs.frame?.contentWindow?.postMessage({
        type: 'view-gallery-showcase-playback',
        channel: this.channel,
        paused: this.effectivePaused,
      }, window.location.origin);
    },
  },
};
</script>

