.view-gallery-live-poster button{padding:.65rem 0 .42rem;border:0;border-bottom:1px solid color-mix(in srgb,currentColor 40%,transparent);background:none;color:inherit;font:500 .7rem/1.3 "Quattrocento Sans",sans-serif;letter-spacing:.04em;cursor:var(--site-interactive-cursor)}
