.view-gallery-live-loading span{width:5px;height:5px;border-radius:50%;background:currentColor;animation:view-gallery-pulse 1.15s ease-in-out infinite}.view-gallery-live-loading span:nth-child(2){animation-delay:110ms}.view-gallery-live-loading span:nth-child(3){animation-delay:220ms}
