.view-gallery-live-modes span{font:500 .78rem/1.3 "Quattrocento Sans",sans-serif}.view-gallery-live-modes small{font:400 .68rem/1.35 "Quattrocento Sans",sans-serif;color:var(--site-text-tertiary)}
.view-gallery-live-actions{display:flex;align-items:center;gap:.35rem;flex:none;margin-left:auto}.view-gallery-live-actions a{color:inherit;font:500 .76rem/1.4 "Quattrocento Sans",sans-serif;text-decoration:underline;text-decoration-color:color-mix(in srgb,currentColor 35%,transparent);text-underline-offset:5px}.view-gallery-live-actions a span{display:inline-block;margin-left:.25rem;transition:transform 180ms cubic-bezier(.23,1,.32,1)}
.view-gallery-live-transport{display:grid;place-items:center;width:2rem;height:2rem;padding:0;border:0;border-radius:50%;background:none;color:var(--site-text-secondary);cursor:var(--site-interactive-cursor);transition:background 180ms ease,color 180ms ease}.view-gallery-live-transport svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.25;stroke-linecap:round;stroke-linejoin:round}
