@media(max-width:700px){.view-gallery-caption{margin:0;max-width:32rem;font:13px/1.55 "Quattrocento Sans",sans-serif;color:var(--site-text-secondary)}
.view-gallery-live-stage figcaption{align-items:center}.view-gallery-live-modes{width:100%;gap:.7rem}.view-gallery-live-modes button{min-width:0;flex:1}.view-gallery-live-modes small{display:none}.view-gallery-live-actions a{display:none}}
@media(prefers-reduced-motion:reduce){.view-gallery-live-loading span{animation:none}.view-gallery-live-modes button,.view-gallery-live-modes button::after,.view-gallery-live-actions a span{transition:none}}
</style>
