<template>
  <div class="gallery-experience-study">
    <section v-for="study in studies" :key="study.id" class="experience-collection" :aria-labelledby="headingId(study.id)">
      <div class="experience-copy">
        <h4 :id="headingId(study.id)">{{ study.title }}</h4>
        <div class="experience-descriptions" aria-live="polite" aria-atomic="true">
          <p>{{ study.active.copy }}</p>
        </div>
        <details v-if="study.active.mechanism" :key="study.active.id" class="experience-mechanism">
          <summary>{{ study.active.mechanism.title }}<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 8h10"/><path class="disclosure-vertical" d="M8 3v10"/></svg></summary>
          <div class="mechanism-copy"><p v-for="paragraph in study.active.mechanism.paragraphs" :key="paragraph">{{ paragraph }}</p></div>
        </details>
      </div>
      <div class="experience-visual">
        <div class="experience-screen">
          <GalleryStudyFilm v-if="study.active.video" :key="study.active.id" :src="film(study.active.video)" :poster="image(study.active.image)" :captions="study.active.sound ? film('audio', 'vtt') : undefined" :label="study.active.caption" :sound="study.active.sound" />
          <figure v-else>
            <ExpandableProjectMedia :title="study.active.title" :aspect-ratio="1920/1046" :interactive="study.active.comparison">
              <GalleryLightComparison v-if="study.active.comparison" :light="themedImage(study.active.image, false)" :dark="themedImage(study.active.image, true)" :alt="study.active.alt" />
              <div v-else class="experience-image">
                <img :src="image(study.active.image, study.active.themed)" :alt="study.active.alt" width="1920" height="1046" loading="lazy" decoding="async" />
                <svg v-if="study.active.id === 'rooms'" class="rooms-focus-mask" viewBox="0 0 1920 1046" aria-hidden="true">
                  <defs><mask :id="maskId"><rect width="1920" height="1046" fill="white"/><rect x="32" y="132" width="489" height="728" rx="2" fill="black"/></mask></defs>
                  <rect width="1920" height="1046" fill="#171610" fill-opacity=".48" :mask="`url(#${maskId})`"/>
                </svg>
              </div>
              <template #caption>
                <figcaption>
                  <span>{{ study.active.caption }}</span>
                  <div v-if="study.active.themed" class="experience-controls">
                  <button class="experience-theme" type="button" :aria-label="galleryDark ? 'Use light theme for Gallery images' : 'Use dark theme for Gallery images'" :aria-pressed="galleryDark" @click="themeOverride = !galleryDark">
                    <svg viewBox="0 0 20 20" aria-hidden="true"><template v-if="galleryDark"><circle cx="10" cy="10" r="3.5"/><path d="M10 1v2m0 14v2M1 10h2m14 0h2M3.6 3.6 5 5m10 10 1.4 1.4M3.6 16.4 5 15M15 5l1.4-1.4"/></template><path v-else d="M16.8 12.4A7 7 0 0 1 7.6 3.2a7 7 0 1 0 9.2 9.2Z"/></svg>
                  </button>
                  </div>
                </figcaption>
              </template>
            </ExpandableProjectMedia>
          </figure>
        </div>
        <div class="experience-frames" role="group" :aria-label="`${study.title} images`">
          <button v-for="feature in study.features" :key="feature.id" type="button" :aria-pressed="selected[study.id] === feature.id" :aria-label="`Show ${feature.title}`" @click="selected[study.id] = feature.id">
            <span class="experience-thumbnail">
              <template v-if="feature.comparison">
                <img :src="themedImage(feature.image, true)" alt="" width="1920" height="1046" loading="lazy" decoding="async" />
                <img class="thumbnail-light" :src="themedImage(feature.image, false)" alt="" width="1920" height="1046" loading="lazy" decoding="async" />
                <span class="thumbnail-divider" aria-hidden="true"><svg viewBox="0 0 20 20"><circle cx="10" cy="10" r="8"/><path d="m8 7-3 3 3 3m4-6 3 3-3 3"/></svg></span>
              </template>
              <img v-else :src="image(feature.image, feature.themed)" alt="" width="1920" height="1046" loading="lazy" decoding="async" />
            </span>
            <span class="experience-frame-label"><ExhibitionFeatureIcon :feature="feature.id" /><span>{{ feature.label }}</span></span>
          </button>
        </div>
      </div>
    </section>
  </div>
</template>
<script>
import GalleryStudyFilm from './GalleryStudyFilm.vue';
import GalleryLightComparison from './GalleryLightComparison.vue';
import ExpandableProjectMedia from './ExpandableProjectMedia.vue';
import ExhibitionFeatureIcon from './ExhibitionFeatureIcon.vue';
import { initialExhibitionDarkMode } from '../../utils/exhibitionTheme';

const features = [
  {
    id: 'hall-across', label: 'Interior', title: 'The Gallery interior', image: 'hall-across', themed: true, caption: 'An open view through the Gallery',
    copy: 'I arranged browsing, creating a View and exploring the archive around one open Hall. Visitors can see these areas together and move towards whichever interests them. The selected exhibition appears at the entrance across the room.',
    alt: 'An oblique view across the Gallery hall showing the collection display, exhibition entrance and archive',
  },
  {
    id: 'building', label: 'Building form', title: 'The building as a whole', image: 'building', themed: true, caption: 'The Gallery seen as a whole',
    copy: 'The exterior view shows how the Hall and exhibition rooms fit together. A continuous base and connected roofs join the spaces, while the openings reveal the routes through the building.',
    alt: 'The complete Gallery building viewed from outside, with Henry’s personal note alongside it',
  },
  {
    id: 'orientation', label: 'Floor plan', title: 'Orientation within the Gallery', image: 'orientation', themed: true, caption: 'A floor plan within the space',
    copy: 'Visitors can choose a location on the floor plan to see a preview, read what they can do there and go directly to it. The map also marks their current position, so they can relate each destination to where they are.',
    alt: 'The Gallery’s visitor guide open over the hall, showing its floor plan and a preview of the entrance hall',
  },
  {
    id: 'light-dark', label: 'Light and dark', title: 'Two lighting treatments', image: 'hall-front', comparison: true, caption: 'Two lighting treatments',
    copy: 'The light theme spreads daylight-like illumination across the Hall. In the dark theme, the collection and exhibition entrance remain lit against darker walls. Both treatments use the same building and display positions.',
    alt: 'The same front-facing view of the Hall in light and dark themes, separated by a movable divider',
  },
  {
    id: 'arrival', label: 'Arrival', title: 'The exhibition entrance', image: 'arrival', caption: 'At the exhibition threshold',
    copy: 'The entrance introduces the View through its title, illustration and opening text. Visitors can see into the first room before entering. A short guide introduces the movement controls and how to open a work.',
    alt: 'The exhibition entrance, its opening narrative and the introductory guide',
  },
  {
    id: 'walls', label: 'Wall writing', title: 'A narrative on the walls', image: 'wall-writing', caption: 'A life across places',
    copy: 'Each room places its chapter introduction beside the works it discusses. Visitors can read the connection and then examine those works. Titles above the doorways identify the next chapter as they move through the exhibition.',
    alt: 'A chapter introduction printed on the gallery wall beside an original photograph',
  },
  {
    id: 'objects', label: 'Objects', title: 'Material with a physical form', image: 'globe', caption: 'Where I’ve Wandered',
    copy: 'Travel records appear on a globe, writing sits on reading stands, and photographs hang as framed works. Visitors can approach an exhibit and open its original content, including the working demos for interactive projects.',
    alt: 'The original travel record presented as a globe with pins marking the places Henry has visited',
    mechanism: {
      title: 'How material becomes an exhibit',
      paragraphs: ['Each source has a registered type that maps to a display form. The layout uses the display’s dimensions and required viewing distance to place it in the room. Interactive projects retain their Vue components when opened, preserving their controls and behaviour.'],
    },
  },
  {
    id: 'afterword', label: 'Afterword', title: 'Closing the exhibition', image: 'afterword', caption: 'An afterword and a visitors’ book',
    copy: 'The final room brings the narrative to a close with an afterword. A visitors’ book beside it lets people leave a response and read what others have written about the exhibition.',
    alt: 'The final exhibition room with its afterword and visitors’ book',
  },
  {
    id: 'rooms', label: 'Route', title: 'A route shaped by the reading', image: 'rooms', caption: 'The visit map',
    copy: 'Each chapter gets a room sized for its works, and doorways connect the rooms in reading order. The visit map shows this route and lets visitors jump to a chapter or a particular work.',
    alt: 'The visit map shows the generated rooms, their connections and individual works',
    mechanism: {
      title: 'How the rooms are composed',
      paragraphs: ['The layout algorithm groups works by chapter and sizes each room around their display forms and viewing distances. It arranges entrances, wall introductions and exhibits, then connects the rooms with doorways and a walkable route.'],
    },
  },
  {
    id: 'lighting', label: 'Lighting', title: 'Lighting the visit', image: 'lighting', video: 'lighting', caption: 'Room lighting',
    copy: 'The next room begins to brighten as a visitor approaches its doorway. Rooms they have left gradually dim, keeping the works ahead visible and making the route easier to follow.',
    mechanism: {
      title: 'How light follows the visitor',
      paragraphs: ['The visitor’s position and distance from a doorway determine which rooms are lit. Each room’s lights fade together, making the next space visible as the visitor approaches its threshold.'],
    },
  },
  {
    id: 'audio', label: 'Audio guide', title: 'An audio guide in my voice', image: 'audio', video: 'audio', caption: 'Audio guide', sound: true,
    copy: 'An AI voice trained on my recordings narrates the exhibition as visitors move through it. They can look at the works while listening, or follow the highlighted words in the reading panel.',
    mechanism: {
      title: 'How narration follows the visit',
      paragraphs: ['Narration connects each passage to a viewing position. A passage can finish as the visitor moves, and the next begins once they arrive. The reading panel follows the active passage, with word highlighting synchronised to playback.', 'Listening progress is remembered for each passage, so visitors can pause, explore a work and pick up where they left off.'],
    },
  },
  {
    id: 'language', label: 'Language', title: 'Reading in another language', image: 'translation', video: 'translation', caption: 'Chinese → English',
    copy: 'Visitors can choose a language for the exhibition’s narrative and audio guide. The translated text and narration follow the same rooms and works, so they can change language during a visit.',
  },
];

const collections = [
  { id: 'gallery', title: 'Spatial design', ids: ['hall-across', 'orientation', 'building', 'light-dark'] },
  { id: 'exhibition', title: 'Exhibition design', ids: ['arrival', 'walls', 'objects', 'afterword'] },
  { id: 'atmosphere', title: 'Movement and guidance', ids: ['rooms', 'lighting', 'audio', 'language'] },
];

export default {
  components: { GalleryStudyFilm, GalleryLightComparison, ExpandableProjectMedia, ExhibitionFeatureIcon },
  data: () => ({ selected: {gallery:'hall-across', exhibition:'arrival', atmosphere:'rooms'}, dark: initialExhibitionDarkMode(), themeOverride: null }),
  computed: {
    maskId() { return `rooms-study-mask-${this.$.uid}`; },
    galleryDark() { return this.themeOverride ?? this.dark; },
    studies() {
      return collections.map(collection => {
        const items = collection.ids.map(id => features.find(feature => feature.id === id));
        return { ...collection, features: items, active: items.find(feature => feature.id === this.selected[collection.id]) };
      });
    },
  },
  mounted() {
    this.syncTheme(); window.addEventListener('theme-change', this.syncTheme);
    this._imageObserver = new IntersectionObserver(([entry]) => {
      if (!entry.isIntersecting) return;
      for (const feature of features.filter(feature => feature.themed || feature.comparison)) for (const dark of [false, true]) {
        const image = new Image(); image.src = this.themedImage(feature.image, dark); image.decode().catch(() => {});
      }
      this._imageObserver.disconnect();
    }, {rootMargin:'300px'});
    this._imageObserver.observe(this.$el.querySelector('.experience-collection'));
  },
  beforeUnmount() { window.removeEventListener('theme-change', this.syncTheme); this._imageObserver?.disconnect(); },
  methods: {
    syncTheme() { this.dark = initialExhibitionDarkMode(); },
    headingId(id) { return `experience-${this.$.uid}-${id}`; },
    themedImage(name, dark) { return `/assets/img/projects/gallery-experience/${name}-${dark ? 'dark' : 'light'}.webp?v=20260925`; },
    image(name, themed = false) { return `/assets/img/projects/gallery-experience/${name}${themed ? `-${this.galleryDark ? 'dark' : 'light'}` : ''}.webp?v=20260925`; },
    film(name, extension = 'mp4') { return `/assets/video/gallery-experience/${name}.${extension}${name === 'translation' ? '' : name === 'afterword' ? '?v=20260921-2' : '?v=20260920'}`; },
  },
};
</script>
