.experience-copy h4 { margin-bottom: 1rem; }
.experience-descriptions p { margin: 0; }
.experience-screen, figure { margin: 0; min-width: 0; }
.experience-image { position: relative; }
img { display: block; width: 100%; height: auto; aspect-ratio: 1920/1046; }
figcaption { display: flex; justify-content: space-between; align-items: center; gap: 1rem; min-height: 2.6rem; font: 13px/1.4 'Quattrocento Sans', sans-serif; color: var(--site-text-secondary); }
.experience-controls { display: flex; align-items: center; gap: .55rem; }
.experience-controls button { display: inline-flex; align-items: center; justify-content: center; gap: .4rem; min-height: 36px; padding: 6px 0; border: 0; background: none; color: inherit; font: inherit; white-space: nowrap; cursor: var(--site-interactive-cursor, pointer); transition: opacity 160ms ease, transform 160ms ease; }
.experience-controls .experience-theme { width: 36px; padding: 9px; }
.experience-controls svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.2; stroke-linecap: round; stroke-linejoin: round; }
.experience-frames { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .8rem; margin-top: .7rem; }
.experience-frames button { min-width: 0; padding: 0 0 .75rem; border: 0; border-bottom: 1px solid transparent; border-radius: 0; background: none; text-align: left; color: var(--site-text-secondary); cursor: var(--site-interactive-cursor, pointer); transition: color 160ms ease, border-color 160ms ease; }
.experience-frames button[aria-pressed="true"] { color: var(--site-text-primary); border-color: currentColor; }
.experience-thumbnail { position: relative; display: block; overflow: hidden; opacity: .65; transition: opacity 160ms ease; }
.thumbnail-light { position: absolute; inset: 0; clip-path: inset(0 50% 0 0); }
.thumbnail-divider { position: absolute; inset: 0 auto 0 50%; width: 1px; background: #fff; }
