.experience-frames button[aria-pressed="true"] .experience-thumbnail { opacity: 1; }
.experience-frame-label { display: flex; align-items: center; gap: .5rem; padding-top: .6rem; font: 13px/1.4 'Quattrocento Sans', sans-serif; }
.experience-frame-label :deep(.exhibition-feature-icon) { width: 24px; height: 24px; flex-shrink: 0; }
