.ask-example-sources a{display:block;width:fit-content;font:12px/1.55 'Quattrocento Sans',sans-serif;color:var(--site-text-secondary);margin:5px 0;text-decoration:underline;text-underline-offset:3px;text-decoration-color:color-mix(in srgb,currentColor 25%,transparent)}
