<template>
  <div class="gallery-light-comparison" :style="{'--reveal':`${reveal}%`}">
    <img :src="dark" :alt="alt" width="1920" height="1046" draggable="false" @load="imageReady" />
    <img class="comparison-light" :src="light" alt="" width="1920" height="1046" draggable="false" @load="imageReady" />
    <span v-show="reveal > 12" class="comparison-label is-light" aria-hidden="true">Light</span>
    <span v-show="reveal < 88" class="comparison-label is-dark" aria-hidden="true">Dark</span>
    <div class="comparison-divider" aria-hidden="true"><span><svg viewBox="0 0 24 24"><path d="m9 8-4 4 4 4m6-8 4 4-4 4"/></svg></span></div>
    <input v-model.number="reveal" class="comparison-input" type="range" min="0" max="100" step="1" aria-label="Compare light and dark Gallery lighting" :aria-valuetext="`${Math.round(reveal)} percent light, ${100-Math.round(reveal)} percent dark`" @pointerdown="takeControl" @keydown="takeControl" @focus="takeControl" />
  </div>
</template>
<script>
export default {
  props: {light: {type:String,required:true}, dark: {type:String,required:true}, alt: String},
  data: () => ({reveal:50}),
  mounted() {
    this._motion = window.matchMedia('(prefers-reduced-motion: reduce)');
    this._motion.addEventListener('change', this.syncPreview);
    this._observer = new IntersectionObserver(([entry]) => {
      this._visible = entry.isIntersecting;
      this.syncPreview();
    }, {threshold:.5});
    this._observer.observe(this.$el);
    document.addEventListener('visibilitychange', this.syncPreview);
    this.imageReady();
  },
  beforeUnmount() {
    this.stopPreview();
    this._observer?.disconnect();
    this._motion?.removeEventListener('change', this.syncPreview);
    document.removeEventListener('visibilitychange', this.syncPreview);
  },
  methods: {
    imageReady() {
      this._ready = [...this.$el.querySelectorAll('img')].every(img => img.complete && img.naturalWidth);
      this.syncPreview();
    },
    stopPreview() { cancelAnimationFrame(this._frame); this._frame = null; },
    takeControl() { this._interacted = true; this.stopPreview(); },
    syncPreview() {
      this.stopPreview();
      if (!this._ready || !this._visible || this._interacted || this._motion?.matches || document.hidden) return;
      // One quiet sweep introduces the divider. The visitor owns it as soon
      // as they focus or touch it, and it rests at an even split afterwards.
      let previous;
      const tick = now => {
        this._elapsed = (this._elapsed || 0) + (previous ? now - previous : 0);
        previous = now;
        const progress = Math.min(1, this._elapsed / 4800);
        this.reveal = 50 + 32 * Math.sin(progress * Math.PI * 2) * Math.sin(progress * Math.PI);
        if (progress < 1) this._frame = requestAnimationFrame(tick);
        else { this.reveal = 50; this._interacted = true; this._frame = null; }
      };
      this._frame = requestAnimationFrame(tick);
    },
  },
};
</script>
